import json,glob,collections
starts=collections.defaultdict(list)
for f in glob.glob('.sofar/initiatives/*/events.jsonl'):
    slug=f.split('/')[2]
    for line in open(f):
        line=line.strip()
        if not line: continue
        try: e=json.loads(line)
        except: continue
        if e.get('type')=='session_started':
            starts[e.get('session')].append((slug,e.get('source'),e.get('ts')))
multi={s:v for s,v in starts.items() if len(v)>1}
print(f"sessions with session_started in >1 initiative: {len(multi)}\n")
for s,v in sorted(multi.items()):
    v.sort(key=lambda x:x[2])
    print(f"  {s[:12]:14} " + " | ".join(f"{sl}({src})" for sl,src,_ in v))
print("\nsource of the SECOND+ registration (the suspicious one):")
print(collections.Counter(src for v in multi.values() for _,src,_ in sorted(v,key=lambda x:x[2])[1:]))
